package cli

import (
	"fmt"
	"strings"

	"github.com/stricttools/strictcli/go/strictcli"

	"github.com/stricttools/rlsbl/internal/release"
)

const unreleasedHelp = "List the commits of the releasable the working directory selects since the nearest release this checkout contains, newest " +
	"first, each marked COVERED when an unreleased changelog entry names it, EXEMPT when it needs no entry (it carries the Autogenerated: true trailer, " +
	"or changes only rlsbl's own records), and MISSING otherwise, with the coverage count. Only commits changing a file of the releasable's members or " +
	"its own records are listed, and in a fork the upstream's history is left out. The releasable's latest release is named when this checkout does " +
	"not contain it. A member versioned under no releasable has no changelog and is refused."

func registerUnreleased(r *commandSet) {
	commit := map[string]any{
		"hash":    schemaString,
		"subject": schemaString,
		"author":  schemaString,
		"date":    schemaString,
		"exempt":  map[string]any{"type": "boolean"},
		"covered": map[string]any{"type": "boolean"},
	}
	properties := latestSchemaProperties()
	properties["releasable"] = schemaString
	properties["nearest_release"] = schemaNullString
	properties["commits"] = map[string]any{"type": "array", "items": closedObject(false, commit)}
	properties["coverage"] = closedObject(false, schemaCoverageShape)
	r.add(command{
		path:    []string{"unreleased"},
		help:    unreleasedHelp,
		effect:  readOnly,
		payload: closedObject(false, properties),
		render:  renderUnreleased,
		run: func(ctx *strictcli.Context, _ map[string]any) (any, error) {
			dir, root, err := workingRepository()
			if err != nil {
				return nil, err
			}
			fork, err := forkHistory(ctx.Effects(), root)
			if err != nil {
				return nil, err
			}
			return release.ReadUnreleased(ctx.Effects(), dir, fork)
		},
	})
}

func renderUnreleased(payload any) string {
	u, err := decodePayload[release.Unreleased](payload)
	if err != nil {
		return renderJSON(payload)
	}
	if len(u.Commits) == 0 {
		return "No unreleased commits."
	}
	since := "(no release in this history)"
	if u.NearestRelease != nil {
		since = *u.NearestRelease
	}
	lines := []string{fmt.Sprintf("Unreleased commits of %s since %s (%d):", u.Releasable, since, len(u.Commits)), ""}
	if u.LatestReleaseInCheckout != nil && !*u.LatestReleaseInCheckout {
		lines = append(lines, "Latest release: "+u.LatestReleaseLabel, "")
	}
	for _, c := range u.Commits {
		state := "[MISSING]"
		switch {
		case c.Exempt:
			state = "[EXEMPT]"
		case c.Covered:
			state = "[COVERED]"
		}
		lines = append(lines, fmt.Sprintf("  %s  %s  %s", c.Hash[:min(7, len(c.Hash))], c.Subject, state))
	}
	lines = append(lines, "", "Coverage: "+coverageText(u.Coverage)+".")
	return strings.Join(lines, "\n")
}
